const https = require("https");
const fs = require("fs");
const version = "{{MC_VERSION}}";

function get(url) {
  return new Promise((resolve, reject) => {
    https.get(url, { headers: { "user-agent": "terrypanel" } }, (res) => {
      if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
        res.resume();
        return get(res.headers.location).then(resolve, reject);
      }
      const chunks = [];
      res.on("data", (c) => chunks.push(c));
      res.on("end", () => resolve({ status: res.statusCode, body: Buffer.concat(chunks) }));
    }).on("error", reject);
  });
}

(async () => {
  const buildsRes = await get(`https://api.papermc.io/v2/projects/paper/versions/${version}/builds`);
  if (buildsRes.status !== 200) throw new Error(`Paper builds API returned ${buildsRes.status} for ${version}`);
  const builds = JSON.parse(buildsRes.body.toString("utf8")).builds;
  const build = builds[builds.length - 1].build;
  const url = `https://api.papermc.io/v2/projects/paper/versions/${version}/builds/${build}/downloads/paper-${version}-${build}.jar`;
  console.log(`Downloading Paper ${version} build ${build}`);
  const jar = await get(url);
  if (jar.status !== 200) throw new Error(`Paper download returned ${jar.status}`);
  fs.writeFileSync("server.jar", jar.body);
  console.log(`Saved server.jar (${(jar.body.length / 1024 / 1024).toFixed(1)} MB)`);
})().catch((err) => {
  console.error(err.message);
  process.exit(1);
});
